class Solution:
    def minCostClimbingStairs(self, cost: List[int]) -> int:
        n = len(cost)
        dp = [0] * (n + 1)                  # 边界 dp[0] = dp[1] = 0：从第 0 或第 1 阶出发不花钱
        for i in range(2, n + 1):
            dp[i] = min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2])  # 跨 1 步或跨 2 步上来
        return dp[n]                        # 楼顶是第 n 阶

