            view(i, false, {
              feeds: [
                { from: i - 1, to: i, win: one <= two, label: `+${C[i - 1]}` },
                { from: i - 2, to: i, win: two < one, label: `+${C[i - 2]}` },
              ],
            }),
            {
              at: "step",
