                ["跨 1 步", `${dp[i - 1]}+${C[i - 1]}=${one}`],
                ["跨 2 步", `${dp[i - 2]}+${C[i - 2]}=${two}`],
                dp[i] !== prevDp ? [`dp[${i}]`, dp[i], prevDp] : [`dp[${i}]`, dp[i]],
              ],
            },
          );
          prevDp = dp[i];
