class Solution {
    public int uniquePathsWithObstacles(int[][] obstacleGrid) {
        int m = obstacleGrid.length, n = obstacleGrid[0].length;
        int[][] dp = new int[m][n];             // dp[i][j]：走到 (i, j) 的路径数
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (obstacleGrid[i][j] == 1) {  // 障碍：走不到
                    dp[i][j] = 0;
                } else if (i == 0 && j == 0) {  // 起点，直接给定
                    dp[i][j] = 1;
                } else {                        // 从上面来 + 从左边来，越界的当 0
                    dp[i][j] = (i > 0 ? dp[i - 1][j] : 0) + (j > 0 ? dp[i][j - 1] : 0);
                }
            }
        }
        return dp[m - 1][n - 1];
    }
}

