func uniquePathsWithObstacles(obstacleGrid [][]int) int {
	m, n := len(obstacleGrid), len(obstacleGrid[0])
	dp := make([][]int, m) // dp[i][j]：走到 (i, j) 的路径数
	for i := range dp {
		dp[i] = make([]int, n)
	}
	for i := 0; i < m; i++ {
		for j := 0; j < n; j++ {
			if obstacleGrid[i][j] == 1 { // 障碍：走不到
				dp[i][j] = 0
			} else if i == 0 && j == 0 { // 起点，直接给定
				dp[i][j] = 1
			} else { // 从上面来 + 从左边来，越界的当 0
				up, left := 0, 0
				if i > 0 {
					up = dp[i-1][j]
				}
				if j > 0 {
					left = dp[i][j-1]
				}
				dp[i][j] = up + left
			}
		}
	}
	return dp[m-1][n-1]
}

