class Solution:
    def knapsack(self, weights: List[int], values: List[int], capacity: int) -> int:
        n = len(weights)
        dp = [[0] * (capacity + 1) for _ in range(n + 1)]   # 边界：dp[0][c] = 0，没有物品就没有价值
        for i in range(1, n + 1):
            w, v = weights[i - 1], values[i - 1]
            for c in range(capacity + 1):
                dp[i][c] = dp[i - 1][c]                     # 不选第 i 件
                if c >= w:                                  # 装得下才能选
                    dp[i][c] = max(dp[i][c], dp[i - 1][c - w] + v)  # 选：让出 w 的容量，价值多 v
        return dp[n][capacity]

